INSERT INTO `_3_database_1_collection_5` VALUES
(1,'699588900008bffcb2d1','2026-02-18 09:38:24.035','2026-02-18 09:38:24.035','[]','Computer Society','cs','Advancing the theory, practice, and application of computer and information processing science and technology.','/Societies/cs.png',''),
(2,'69958890001d23480eeb','2026-02-18 09:38:24.362','2026-02-18 09:38:24.362','[]','Robotics & Automation Society','ras','The IEEE RAS Sahrdaya Student Branch Chapter is committed to advancing robotics and automation through innovation, collaboration, and hands-on learning. Our mission is to cultivate technical excellence by organizing workshops, seminars, and training sessions led by industry experts and researchers. We provide opportunities for members to develop their skills through real-world projects, technical competitions, and interactive sessions on cutting-edge tools and technologies. Join us to explore the future of robotics and automation while collaborating with a dynamic community of enthusiasts and professionals.','/Societies/ras.png','https://i.ibb.co/F4fdkmLz/photo-2025-02-28-18-25-22-2.jpg'),
(3,'69958890003135f35f0b','2026-02-18 09:38:24.681','2026-02-18 09:38:24.681','[]','Women in Engineering','wie','Inspiring, engaging, encouraging, and empowering IEEE women members worldwide.','/Societies/wie.png',''),
(4,'69958891000666bcd7e2','2026-02-18 09:38:25.164','2026-02-18 09:38:25.164','[]','Industry Applications Society','ias','Advancing the theory and practice of electrical and electronic engineering in industrial applications.','/Societies/ias.png',''),
(5,'69958891002d0f991342','2026-02-18 09:38:25.620','2026-02-18 09:38:25.620','[]','Power & Energy Society','pes','The PES Society at IEEE Sahrdaya SB is a dynamic community dedicated to the fields of power and energy. Our mission is to cultivate knowledge, innovation, and collaboration in electrical power. We achieve this through a variety of activities, including workshops, seminars, and lectures featuring industry experts and academicians, which foster knowledge sharing. We also offer training sessions to develop technical skills and proficiency with software tools. Members engage in hands-on projects that apply theoretical knowledge, and participate in technical competitions designed to challenge and refine their skills. Join us to delve into the exciting world of power and energy.','/Societies/pes.png',''),
(6,'6995889200029b375197','2026-02-18 09:38:25.936','2026-02-18 09:38:25.936','[]','SIGHT','sight','Special Interest Group on Humanitarian Technology - applying technology for the benefit of humanity.','/Societies/sight.png',''),
(7,'699588920015ce8fc81b','2026-02-18 09:38:26.255','2026-02-18 09:38:26.255','[]','Engineering in Medicine & Biology','embs','Advancing medicine and biology through the application of engineering sciences and technology.','/Societies/embs.png',''),
(8,'69958892002a096493b5','2026-02-18 09:38:26.590','2026-02-18 09:38:26.590','[]','Signal Processing Society','sps','The IEEE Signal Processing Society (SPS) at Sahrdaya SB is dedicated to advancing knowledge and expertise in signal processing and its applications. Our mission is to drive innovation and foster collaboration through a diverse range of activities. We organize workshops, seminars, and expert talks featuring leading industry professionals and academics. Additionally, we offer hands-on training sessions to enhance technical skills in areas such as digital signal processing (DSP), machine learning, and embedded systems.\\n\\nMembers have the opportunity to work on real-world projects, research initiatives, and technical competitions, applying their knowledge to solve practical challenges. By joining SPS, you gain access to mentorship, networking opportunities, and resources that empower you to explore and excel in this dynamic field. Whether you\'re a beginner or an expert, SPS provides the platform to innovate, collaborate, and lead in signal processing.','/Societies/sps.png',''),
(9,'699588930000d821e360','2026-02-18 09:38:26.921','2026-02-18 09:38:26.921','[]','Circuits and Systems Society','cas','This society at IEEE Sahrdaya SB is dedicated to advancing knowledge and expertise in its specialized field. Our mission is to drive innovation and foster collaboration through a diverse range of activities. We organize workshops, seminars, and lectures with leading industry professionals and academics, as well as offer training sessions to enhance technical skills and tool proficiency. Members have the opportunity to work on practical projects that apply their knowledge and engage in competitions that test and refine their abilities. Join us to explore and excel in this vibrant area of study','/Societies/cas.png',''),
(10,'69958893001494f61313','2026-02-18 09:38:27.261','2026-02-18 09:38:27.261','[]','Communication Society','css','A global community of researchers, practitioners, and educators in communications and networking.','/Societies/css.png',''),
(11,'69958893002b079465d9','2026-02-18 09:38:27.581','2026-02-18 09:38:27.581','[]','Education Society','edsoc','Advancing excellence in electrical, electronics, and computer engineering education.','/Societies/edsoc.png',''),
(12,'69958893003e0d1997ef','2026-02-18 09:38:27.941','2026-02-18 09:38:27.941','[]','Industrial Electronics Society','ies','Encompassing theory and application of electronics, controls and communications, instrumentation and computational intelligence.','/Societies/ies.png',''),
(13,'69958894001695828ca5','2026-02-18 09:38:28.270','2026-02-18 09:38:28.270','[]','Nuclear & Plasma Sciences Society','npss','Advancing the fields of nuclear and plasma sciences and engineering.','/Societies/npss.png',''),
(14,'69958894002a5c757f2e','2026-02-18 09:38:28.583','2026-02-18 09:38:28.583','[]','Photonics Society','ps','This society at IEEE Sahrdaya SB is dedicated to advancing knowledge and expertise in its specialized field. Our mission is to drive innovation and foster collaboration through a diverse range of activities. We organize workshops, seminars, and lectures with leading industry professionals and academics, as well as offer training sessions to enhance technical skills and tool proficiency. Members have the opportunity to work on practical projects that apply their knowledge and engage in competitions that test and refine their abilities. Join us to explore and excel in this vibrant area of study.','/Societies/ps.png','https://i.ibb.co/XWrF1cr/society-bg-Id-Tw-ZKPn-Pvb-E69ubn-YGCr-WYWKII2.jpg');
INSERT INTO `_3_database_1_collection_8` VALUES
(3,'69959e5a00336dd1ebe0','2026-02-18 11:11:22.791','2026-03-26 08:05:03.746','[]','IEEE AGM \'26','Join us as we reflect on a year of innovation, elect the new executive committee, and set the vision for the future of IEEE Sahrdaya SB.','2026-03-30 00:00:00.000','Auditorium',0,'https://backend.mulearnscet.in/v1/storage/buckets/6995847d002df5a82b49/files/69959e7d000ca2de65c2/view?project=69947a65000687b9d761&mode=admin','SB','completed',180,NULL,'2026-03-27 17:38:03.728',0,3,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,0),
(4,'6995b65e000b2f340b62','2026-02-18 12:53:49.959','2026-03-25 19:30:26.296','[]','Debate Competition','A debate competition was held with 20 participants forming four teams, focusing on current and upcoming technologies pros and cons. The aim was to enhance studentΓÇÖs awareness, expertise, and knowledge in the tech field. The competition also provided valuable experience in public speaking and debate skills, with mentorship from collaborating organizations such as ACES, the Department of Computer Science and Engineering,IEEE Women in Engineering, and the IEEE Computer Society. The event was a resounding success.','2025-11-06 11:00:00.000','',0,'https://i.ibb.co/hsrCbRT/event-0-Pg03-RE2mt-Inx-Ryfdnk-H.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,0,2,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,0),
(5,'6995b65e003df64fb592','2026-02-18 12:53:50.668','2026-02-18 12:53:50.668','[]','H20 Forge','The Underwater Robotics workshop named ΓÇÿH20 ForgeΓÇÖ was conducted at IEEE CS SBC GECT in collaboration with IEEE CS SBC CCE, IEEE CS SBC SCET on 7th October 2023 at 09:00 AM to 3:30PM. \nThe goal of the event was to give participants an introduction to Underwater robotics concepts and scope. They delved into design concepts of robotics and roadmap to a robotics carrier and edifice them for future projects in the field. Participants got to see real world robot models and their demonstration. The workshop was a great success and got amazing feedbacks.\n','2023-10-07 00:00:00.000','',0,'https://i.ibb.co/L031qZw/event-2-KUoexwwvd2-C7g7-We-Dj-E.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(6,'6995b65f0022925f32ac','2026-02-18 12:53:51.323','2026-02-18 12:53:51.323','[]','Confidence Development and Entrepreneurship','IEEE CS SCET conducted a talk session on the topic ΓÇ£LEADERSHIP DEVELOPMENTΓÇ¥. The session was held on October 1 at 02:00 PM to 04:00 PM. This session make students more ideas about the qualities which should be followed to become a good leader. Leadership qualities can be implemented in many ways. And overall the session was very much informative and influential.\n','2023-10-01 00:00:00.000','',0,'https://i.ibb.co/Q9RF4N9/event-5-Sr-If-Sl-I5kmdp-FMnip9-L.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(7,'6995b660000cd7797427','2026-02-18 12:53:51.894','2026-02-18 12:53:51.894','[]','Generative AI','\nComputer Society and WIE Affinity Group of IEEE Sahrdaya SB conducted an online WEBINAR on GENERATIVE AI,  on 05 November 2023 through Google meet from 7:30 PM to 8:30 PM.\n\nThe session was handled by Anuvinda Krishnan V K, Analyst, Deloitte USI. The session was started with an introduction speech by Aisha Salim, Vice-Chair of WIE, IEEE Sahrdaya SB.\n\nThe speaker talked about introduction to Generative AI, applications, impact on all industry sectors, future job opportunities etc.\nOverall, the event was very useful for the participants. They found it informative and engaging.\n','2023-11-05 00:00:00.000','',0,'https://i.ibb.co/tC9HJVF/event-GKHi-BUf-B9em-JUCgh6d-Wp.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(8,'6995b6600032ce760a40','2026-02-18 12:53:52.475','2026-02-18 12:53:52.475','[]','Latex Workshop','The Technical Paper Writing event, organized for S7 BM students at Sahrdaya College of Engineering and Technology, witnessed participation from 63 students. Conducted by full-time research scholars from the CSE Department, the event leveraged the Overleaf tool in LaTeX for document preparation. The success of the event is underscored by the active engagement of participants and the seamless collaboration facilitated by Overleaf. Advantages include enhancing studentΓÇÖs research and writing skills, fostering collaboration among scholars, and familiarizing students with LaTeX tools, equipping them with valuable technical communication skills for their academic and professional pursuits.\n','2023-11-08 00:00:00.000','',0,'https://i.ibb.co/qmYymQJ/event-GW2zui2t-Zyw1w-S0-Y9-SXc.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(9,'6995b66100185fe0d1e3','2026-02-18 12:53:53.078','2026-02-18 12:53:53.078','[]','JAM','IEEE CS SCET conducted a JAM on behalf of ENGINEERING DAY, which was held on 15th  September 2023 at 12:30 pm. It was conducted by IEEE COMPUTER SOCIETY .There were  more than 30 students participated in jam and winners were selected on the review of  judging panel. Through this it help the students to improve there confidence and  communication skill.\n','2023-10-15 00:00:00.000','',0,'https://i.ibb.co/RNfpSh1/event-J4e7-Cnn106q-Bi-Fj-LZH0-W.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(10,'6995b661003c5865b59a','2026-02-18 12:53:53.732','2026-02-18 12:53:53.732','[]','Membership Development Drive','The IEEE Computer Society organized a successful membership drive targeted the first year Computer Science students.The event aimed to familiarize students with the societyΓÇÖs offerings and encourage them to become members.The event was conducted on 4th Nov 2023, in their respective classrooms.The event spanned 2 hours and had active participation from 189 students.The session was addressed by Dr.R Satheesh Kumar(Advisor of Computer Society) and Mr.Robin Francis(CS Society chair) emphasized the benefits of society membership, including access to a wide range of resources and networking opportunities.It was a successful event with approximately 100 students expressed their interest in joining the IEEE Computer Society.\n','2023-11-04 00:00:00.000','',0,'https://i.ibb.co/DkKy23j/event-MLyc3s0oxigk-Mgnfxir-Q.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(11,'6995b662002786a24450','2026-02-18 12:53:54.287','2026-02-18 12:53:54.287','[]','Jump Start','The \"Jump Start\" event, organized by the IEEE Computer Society Kerala Chapter, is a Membership Development Session aimed at engaging and expanding the community. Scheduled for November 8, 2023, at 7:00 PM, the session will feature Karthik K as the speaker. Karthik K currently serves as the Joint Secretary for Industry at IEEE CSKS and as the Secretary for IEEE CS SYP. This session is an excellent opportunity for members to learn more about the benefits of IEEE membership, network with peers, and explore new professional development avenues.','2023-11-08 00:00:00.000','',0,'https://i.ibb.co/P4LGyVm/event-NNAw-RFXGPHHgd7x3fva-C.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(12,'6995b663000ae0e3efdf','2026-02-18 12:53:55.208','2026-02-18 12:53:55.208','[]','Mythic Futures: Where Legends Meet the Future','The \"Mythic Futures: Where Legends Meet the Future\" AI Image Generation Competition was successfully conducted from March 13, 2025, at 7:00 PM to March 16, 2025, at 10:00 PM through Google Forms. The event explored the fusion of mythology and futuristic technology, encouraging participants to create AI-generated artwork using tools like DALL┬╖E, MidJourney, and Stable Diffusion.\nA total of 106 participants took part in the competition, ensuring a balanced representation across academic years. 33 (31.13%) were first-year students, 31 (29.24%) were second-year students, and 38 (35.84%) were third-year students, demonstrating active involvement from all levels.\nWith the submission deadline on March 16, 2025, at 10:00 PM, the competition showcased exceptional creativity, blending ancient myths with futuristic innovations. It successfully fostered innovation and artistic expression, highlighting AIΓÇÖs potential in digital storytelling.','2025-03-13 11:00:00.000','',0,'https://i.ibb.co/23wTG59s/Whats-App-Image-2025-03-13-at-19-00-34-7ba96d01.jpg','69958892002a096493b5','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(13,'6995b6640005893f381e','2026-02-18 12:53:55.834','2026-02-18 12:53:55.834','[]','Synergising Computational Sciences for Sustainable Energy Advancement','At St. Joseph CGHSS, 68 students and 4 faculties actively participated in the event titled \'Synergising Computational Science for Sustainable Energy Advancement.\' The session focused on free energy sources, guiding participants in the creation of projects that harness these sustainable alternatives. By emphasizing the role of piezo sensors, attendees gained insights into integrating advanced technology into their projects. The event aimed to raise awareness about the significance of utilizing free energy sources for a brighter future. This initiative reflects fostering a deeper understanding of sustainable practices among its students.','2023-10-18 00:00:00.000','',0,'https://i.ibb.co/B32zKgk/event-OT0-Jxe-VQ57-Tv-Qpw-HTEcs.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(14,'6995b664002e6b9a5428','2026-02-18 12:53:56.369','2026-02-18 12:53:56.369','[]','Product Marketing','The event ΓÇ£Product MarketingΓÇ¥ was conducted on 8th Nov 2023 from 11 AM to 12 PM at CS Project lab.It was a collaborative effort between IEEE Computer Society, ACES, and WIE.The focus of the event was on utilizing various technologies for product marketing in a manner that provides appreciable benefits to society.Participants explored innovative approaches to marketing products that integrate new technologies.14 teams with 5 members each have participated in the event,showcasing innovative solutions that exemplified the integration of new technologies for socially impactful product marketing.','2023-11-08 00:00:00.000','',0,'https://i.ibb.co/ZzQqNBd/event-OYVf6u-L8a3-By0-AOe-M9-GY.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(15,'6995b665000f05d12668','2026-02-18 12:53:56.898','2026-02-18 12:53:56.898','[]','Machine Learning Workshop','The IEEE Sahrdaya SB, in association with the IEEE Computer Society and ACES, is organizing a Machine Learning Bootcamp on February 13-14, 2024, at Sahrdaya College of Engineering & Technology. This two-day intensive training program is designed to provide participants with a comprehensive understanding of machine learning principles, techniques, and tools. It offers a unique opportunity for students, professionals, and enthusiasts to enhance their skills in a rapidly evolving field, guided by expert instructors. Join this bootcamp to dive deep into the world of machine learning, network with like-minded peers, and gain hands-on experience in building intelligent systems.','2024-02-13 00:00:00.000','',0,'https://i.ibb.co/NtkgGdX/event-Pp-Rnh-Fjs-Tt-Arx-CY494r7.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(16,'6995b66500300c433343','2026-02-18 12:53:57.409','2026-02-18 12:53:57.409','[]','Deep Learning Workshop','The Computer Society of IEEE Sahrdaya SB conducted a deep learning workshop for third-year computer science students. The event was led on 13th and 14th of February 2024 from 10:00 AM to 03:30 PM by Arvin Jeostus from IEEE SB GECI TC 2023. The goal of the workshop was to make deep learning easy to understand. Skilled instructor guided students through practical examples and activities. Many students participated eagerly, making it a fun and helpful experience. Overall, it gave students useful skills for their studies and future careers.\n\n','2024-02-13 00:00:00.000','',0,'https://i.ibb.co/KKQjGk0/event-Rvl5p-R2b2-Yxar-Wke-ZQTl.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(17,'6995b66600119478cfa3','2026-02-18 12:53:57.938','2026-02-18 12:53:57.938','[]','Machine Learning Using Python Workshop','IEEE CS SCET conducted a workshop on ΓÇ£MACHINE LEARNING USING PYTHON WORKSHOPΓÇ¥, which was held on 13th & 14th of September 2023 from 09:00 am to 4:00 pm. It was a two day workshop conducted by IEEE COMPUTER SOCIETY. The workshopΓÇÖs main intension is to improve the machine learning using python on the students. On the first day they introduces us about: introduction to machine learning, essential statistics for machine learning, ge╞½ng started with python, data type and conditional and looping statement. On the second day Data Analysis, supervised learning, reinforcement learning, q-learning algorithm. These two day was very much effective and useful for all the students who all attempted and the feedback was good.\n','2023-09-13 00:00:00.000','',0,'https://i.ibb.co/sbJfvQH/event-Suelvu7-D2-DDJ0-O7tr-Lz-L.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(18,'6995b666003362fc4abe','2026-02-18 12:53:58.459','2026-02-18 12:53:58.459','[]','Machine Learning Workshop','\nComputer Society of IEEE Sahrdaya SB conducted a machine learning workshop for third-year computer science students on 13th and 14th of February 2024 from 10:00 AM to 03:30 PM. The event was led by Dr. Anju Pratap, Professor , Department of Computer Science and Engineering at Saintgits College of Engineering.Dr. Anju Pratap\'s knowledge and help made learning better. In the end, the workshop gave students important knowledge and skills in machine learning to help them in their studies and careers.\n','2024-02-13 00:00:00.000','',0,'https://i.ibb.co/vqFhR9v/event-W2o-HJNty-DPe8-QYo0-ZZx-V.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(19,'6995b667001512a6a78e','2026-02-18 12:53:58.993','2026-02-18 12:53:58.993','[]','API 101','The workshop for 2nd year students of Computer Science department was conducted on 18th of April 2023 from 9 AM to 4 PM. The session was handled by MR. Joel Jaison, a student expert in POSTMAN. The workshop on API 101 with Postman was conducted at the computer centre lab (main block) with 54 students attending the session. It was a collaboration of IEEE Sahrdaya SB with ACES Computer Association. The event was a hands-on session.','2023-04-18 00:00:00.000','',0,'https://i.ibb.co/9gB3z49/event-Z9o-I1zx-KUPCnif-Ege-OTU.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(20,'6995b667003715d23eeb','2026-02-18 12:53:59.530','2026-02-18 12:53:59.530','[]','AR/VR Workshop','Computer Society of IEEE Sahrdaya SB organized an AR/VR workshop for third-year computer science students on 12th February 2024 from 10:00 AM to 03:30 PM. The event was led by Mr. Vinay Mathew John, Chief Trainer Officer of ASAP CSP Perumbavoor, and Ms. Pyary, Program Coordinator of ASAP. The workshop aimed to provide practical experience in AR/VR technology. Students took part in activities during their workshop. Their enthusiasm made the workshop enjoyable and informative.\n','2024-02-12 00:00:00.000','',0,'https://i.ibb.co/f8w9qCX/event-c7q-Ots-QTe94t-E6x-Cw-Axk.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(21,'6995b6680019700822bf','2026-02-18 12:54:00.058','2026-02-18 12:54:00.058','[]','AR/VR Bootcamp','The 5-day Technical Bootcamp on Augmented Reality (AR) and Virtual Reality (VR), held from August 5-9, 2024, at Sahrdaya College of Engineering and Technology, offered an immersive learning experience in AR/VR development. Conducted by experts Mr. Akhilesh KS and Mr. Ajith Kumar S V from TILTEDU, the bootcamp blended theoretical sessions with hands-on workshops using tools like Unity and Blender. The event covered AR/VR fundamentals, C# scripting, 3D modeling, game development, mobile deployment, and advanced AR features like plane and face tracking. Participants worked on creating interactive AR/VR applications, culminating in a VR experience and final presentations. The bootcamp concluded with a closing ceremony attended by the college\'s dignitaries, leaving participants with enhanced skills and inspiration to explore the future of AR/VR technologies further. The event was well-received, setting a high standard for future technical programs.','2024-08-05 00:00:00.000','',0,'https://i.ibb.co/JvpSYJc/event-ccec-BDkk0b-NNeii65s-WN.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(22,'6995b668003a9f61ae6e','2026-02-18 12:54:00.613','2026-02-18 12:54:00.613','[]','Leadership And Managerial Session','The IEEE Computer Society has conducted a 1 hour ΓÇ£Leadership And Managerial SessionΓÇ¥ for the selected students from the first years,on 3rd Nov 2023.The session was managed by Mr.Robin Francis (Computer Society Chair) which was focused on leadership and managerial skills.25 students participated in the session, provided with valuable insights and discussions on key aspects of effective leadership within the context of the computer science field.The event aimed to enhance participantsΓÇÖ managerial capabilities and foster a collaborative learning environment.\n','2023-11-03 00:00:00.000','',0,'https://i.ibb.co/qY0M7Rr/event-e-Ql-LD5-Wm9f82yrbz3gkw.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(23,'6995b6690022e97d17db','2026-02-18 12:54:01.194','2026-02-18 12:54:01.194','[]','Online Info Session on AR/VR','The Department of Computer Science and Engineering, in collaboration with the IEEE Computer Society, Sahrdaya, and TILT-EDU, organized an informative session on Augmented Reality (AR) and Virtual Reality (VR). The session, led by TILT-EDU\'s resource persons, Mr. Naveen and Mr. Akhilesh, introduced students to the dynamic fields of AR and VR, showcasing various projects their company has undertaken and highlighting the technologies\' practical applications and future potential. They also announced an upcoming bootcamp on AR and VR, set to start on August 5th, which will provide hands-on training if a minimum of 50 students enroll. The event concluded with an engaging Q&A session, further enriching the participants\' understanding and generating excitement for the bootcamp. This initiative marks a significant step towards empowering students with advanced skills in emerging technologies.','2024-07-22 00:00:00.000','',0,'https://i.ibb.co/LNHLpbb/event-h-Q468-Dku-Bwuyl5-ZBe-MCD.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(24,'6995b66a00055419778d','2026-02-18 12:54:01.725','2026-02-18 12:54:01.725','[]','Bridge The Gap','On 9th of September 2023, from 9:00 am to 4:00 pm, the \"BRIDGE THE GAP: PRE-UNIVERSITY TRACK\" event unfolded as a one-day initiative. With a primary goal of exposing 20 12th-grade students, aspiring for B-tech careers, to diverse computer science technologies and skill sets, the event aimed to foster a balance between continuous skill development and academics. IEEE and CS Society introductions preceded sessions by Dr. R. Satheesh Kumar and Jasmy Davies on the future of computer science and a workshop on C introduction, incurring an expenditure of approximately 5000. The event concluded with valuable feedback affirming its informativeness and quality.','2023-09-09 00:00:00.000','',0,'https://i.ibb.co/j5vns39/event-i-CCCDVTu-Zum6-Hpozkxrr.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(25,'6995b66a00259e56b485','2026-02-18 12:54:02.299','2026-02-18 12:54:02.299','[]','Career In Cloud Computing','\"Career in Cloud Computing\" is an online event organized by IEEE Sahrdaya SB and IEEE SIGHT, featuring Sinu George, a Senior Cloud Delivery Manager. The session, will provide valuable insights into career opportunities and growth in the field of cloud computing. This interactive talk aims to guide and inspire students and professionals interested in exploring the ever-evolving cloud industry.','2025-03-08 00:00:00.000','',0,'https://i.ibb.co/tr91NCK/IMG-20250303-WA0084.jpg','6995889200029b375197','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(26,'6995b66b000bf88e516c','2026-02-18 12:54:02.851','2026-02-18 12:54:02.851','[]','PES Tournament','The e-Football Tournament aimed to provide a relaxing break for students within the curriculum, fostering a refreshed mindset. With 32 participants, the gaming competition featured a cash award and a prize pool of Rs. 500. The event not only offered a recreational outlet but also promoted friendly competition. This initiative recognized the importance of balancing academic rigors with recreational activities, contributing to the holistic development of students. Overall, the PES Tournament successfully achieved its goal of providing a rejuvenating experience for participants.\n','2023-10-01 00:00:00.000','',0,'https://i.ibb.co/7Yk8Bf8/event-kzh-Ry-A3-Lp-FUhj-TDeq7bk.png','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(27,'6995b66b002df47aea86','2026-02-18 12:54:03.429','2026-02-18 12:54:03.429','[]','Cloud Computing','IEEE COMPUTER SOCIETY SCET has conducted a three day internship event on ΓÇ£CLOUD COMPUTINGΓÇ¥ ,which was held on 16-18th of May 2023. Mr. RAJATH NAVAS, MD & Chief Executive officer ,Pace Lab Speaker at IITs and ISROIIST, Founder of Alphadiet private limited were leading the session. There were 50 participants attending throughout the session and feedback has been taken at the end of the day ,the session was really interactive and informative for the participants. Overall the feedback was good.','2023-05-16 00:00:00.000','',0,'https://i.ibb.co/qyC4R7j/event-ljpkv-FP3-Qz-S3q-IBR4-VDq.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(28,'6995b66c00137534247b','2026-02-18 12:54:03.953','2026-02-18 12:54:03.953','[]','Info Session on AR/VR for S3 and S5','The Department of Computer Science and Engineering, in collaboration with the IEEE Computer Society Sahrdaya and TILT-EDU, hosted an informative session on Augmented Reality (AR) and Virtual Reality (VR) to introduce students to the latest advancements and applications in these dynamic fields. Led by Mr. Akhilesh from TILT-EDU, the session delved into AR and VR technologies, featuring various projects undertaken by TILT-EDU and demonstrating their practical applications in real-world scenarios. Mr. Akhilesh\'s discussion highlighted not only the current uses but also the future potential and emerging trends of AR and VR, sparking significant interest among attendees. The session concluded with a Q&A segment, allowing students to clarify their queries and gain deeper insights into these technologies. This initiative marks a significant step by the Department and IEEE Computer Society, Sahrdaya, in equipping students with cutting-edge skills in emerging technologies.','2024-08-07 00:00:00.000','',0,'https://i.ibb.co/wR2ZdgL/event-rfs3b7-Xq-DQ4lb3-FSUa-Rd.jpg','699588900008bffcb2d1','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(29,'6995b66c003483ce7168','2026-02-18 12:54:04.498','2026-02-18 12:54:04.498','[]','Drone/UAS Allied Technologies Bootcamp','The IEEE Sahrdaya RAS, in collaboration with NIELIT and the Ministry of Electronics and IT, organized a five-day Bootcamp on Allied Technologies for Drone/UAS. The event provided participants with a strong foundation in computer vision, AI applications, and hands-on drone programming, bringing together experts, students, and tech enthusiasts.  \n\nDay 1 & 2: Introductory Python & OpenCV by Dr. Nithin G, coordinated by Ms. Geethu T, covered fundamental programming and computer vision concepts, essential for AI-driven drone technology.  \nDay 3 - 5: Hands-on Drone Workshop by Mr. Binu K Joseph, where participants programmed Tello Drones to explore UAS navigation, automation, and real-world applications.  \n\nThe bootcamp concluded with an assessment exam and a valedictory session featuring insights from Mr. Anil Antony and Mr. Sreejesh Sreedharan (Scientific Technical Officer, NIELIT) on the future of drone technology.','2025-02-24 00:00:00.000','',0,'https://i.ibb.co/Rp5tmpQG/drone-bootcamp.jpg','69958890001d23480eeb','completed',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
