(33,'69c9141d00129b07f2ae','2026-03-29 11:59:25.006','2026-03-29 11:59:25.006','[\"read(\\\"user:6995cc738fc55521f797\\\")\",\"update(\\\"user:6995cc738fc55521f797\\\")\",\"delete(\\\"user:6995cc738fc55521f797\\\")\"]','ΓÇïADSSSC  26 International Conference on AI-Driven Solutions for Sustainable Smart Cities: Challenges and Opportunities','ADSSSC ΓÇÖ26, organized by Sahrdaya College of Engineering and Technology and IEEE Sahrdaya SB in collaboration with the IEEE Kerala Section, brings together brilliant minds to explore AI-driven solutions for sustainable smart cities.','2026-04-09 03:30:00.000','Sahrdaya College of Engineering and Technology',1700,'https://backend.ieeesahrdaya.com/v1//storage/buckets/society_images/files/69c9141c0024ab616e07/view?project=69947a65000687b9d761','SB','published',NULL,NULL,'2026-03-27 04:31:13.546',0,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,0);
